"""Undo, redo and history (docs/undo.md)."""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused

STOCK_OPS = ("receive", "issue", "move", "count", "fix")


def stacks(entries):
    """Returns (done, undone, dropped_seqs); undone holds (op, undo_line)."""
    done, undone, dropped = [], [], set()
    for e in entries:
        op = e["op"]
        if op in STOCK_OPS:
            dropped.update(o["seq"] for o, _ in undone)
            undone.clear()
            done.append(e)
        elif op == "undo":
            if not done or done[-1]["seq"] != e.get("target"):
                raise DataError("journal", f"#{e['seq']}: undo does not match")
            undone.append((done.pop(), e))
        elif op == "redo":
            if not undone or undone[-1][0]["seq"] != e.get("target"):
                raise DataError("journal", f"#{e['seq']}: redo does not match")
            done.append(undone.pop()[0])
    return done, undone, dropped


def _changes_v2(effects):
    return [(x["bin"], x["before"]) for x in reversed(effects)]


def _changes_v1(ctx, op, store):
    """(bin, new quantity) pairs that take a format 1 operation back, simulated on a copy."""
    sku = op["sku"]
    q = {}

    def cur(b):
        return q[b] if b in q else store.qty(sku, b)

    out = []

    def setq(b, v):
        q[b] = v
        out.append((b, v))

    kind = op["op"]
    if kind == "receive":
        units = op["qty"]
        if op.get("uom") == "pk":
            if sku not in ctx.items:
                raise Refused("unknown-sku", f"no item {sku}")
            units *= ctx.items[sku].pack_size
        b = normalize(op["bin"])
        setq(b, cur(b) - units)
    elif kind == "issue":
        for b, n in reversed(op["picks"]):
            b = normalize(b)
            setq(b, cur(b) + n)
    elif kind == "move":
        t, f = normalize(op["to"]), normalize(op["from"])
        setq(t, cur(t) - op["qty"])
        setq(f, cur(f) + op["qty"])
    return out


def _apply(ctx, store, sku, pairs):
    for b, _ in pairs:
        if b not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {b}")
    effects = []
    for b, v in pairs:
        before = store.qty(sku, b)
        if v < 0:
            raise DataError("journal", f"{sku} in {b} would go below zero")
        per = store._stock.setdefault(sku, {})
        if v:
            per[b] = v
        else:
            per.pop(b, None)
        effects.append({"bin": b, "before": before, "after": v})
    return effects


def run(ctx, kind, steps):
    done, undone, _ = stacks(ctx.entries)
    store = ctx.store.copy()
    seq = journal.next_seq(ctx.entries)
    new, heads = [], []
    for _ in range(steps):
        if kind == "undo":
            if not done:
                raise Refused("nothing-to-undo", "nothing to undo")
            op = done[-1]
            if op["op"] == "fix":
                raise Refused("barrier", "a fix cannot be undone")
            if op.get("v") == 2:
                pairs = _changes_v2(op["effects"])
            elif op["op"] == "count":
                raise Refused("irreversible", "format 1 count")
            else:
                pairs = _changes_v1(ctx, op, store)
            effects = _apply(ctx, store, op["sku"], pairs)
            done.pop()
            undone.append((op, None))
        else:
            if not undone:
                raise Refused("nothing-to-redo", "nothing to redo")
            op, u = undone[-1]
            effects = _apply(ctx, store, op["sku"], _changes_v2(u["effects"]))
            undone.pop()
            done.append(op)
        e = journal.entry(seq, kind, ctx.by, op["sku"], target=op["seq"], effects=effects)
        if kind == "undo":
            undone[-1] = (op, e)
        new.append(e)
        heads.append(f"#{seq} {kind} {op['sku']} (#{op['seq']} {op['op']})")
        seq += 1
    ctx.commit(store, new)
    lines = []
    for h, e in zip(heads, new):
        lines.append(h)
        lines += [f"  {x['bin']} {x['before']} -> {x['after']}" for x in e["effects"]]
    return lines


def history(ctx, limit):
    done, undone, dropped = stacks(ctx.entries)
    undone_seqs = {o["seq"] for o, _ in undone}
    ops = [e for e in ctx.entries if e["op"] in STOCK_OPS]
    out = []
    for e in reversed(ops[-limit:]):
        s = e["seq"]
        if s in undone_seqs:
            st = "undone"
        elif s in dropped:
            st = "dropped"
        elif e["op"] == "fix":
            st = "barrier"
        else:
            st = "done"
        out.append(f"{s:>5}  {e['op']:<7}  {e.get('sku', ''):<10}  {st}")
    return out
